#!/usr/bin/env node
/**
 * Put the published rule content into the app, as text, with the ledger's digest beside it.
 *
 * ```
 * content/rules/phrase-lexicon.<label>.json   the immutable lexicon
 * content/rules/weights.<label>.json          the immutable weight set
 * content/rules/index.json                    the ledger rows that vouch for them
 *          ↓
 * apps/mobile/src/rules/generated/lexicon.ts  ← committed, --check in gate 11
 * apps/mobile/src/rules/generated/weights.ts  ←
 * ```
 *
 * **Two artefacts, one shape** (F-099). The weights module was added because the app needed the
 * warm/cool POLES and had been carrying its own copy of them as literals — E-038, and E-008's
 * consequence: two definitions of a colour rule, both passing their own tests, drifting the
 * first time an editor publishes a new pole. Bundling the poles as anything other than the
 * published rule set would have been a third representation.
 *
 * The same shape as `generate-corpus-bundle.mjs`, deliberately and for the same three reasons:
 *
 * - **the text and the digest are separate exports**, because a record checked against a
 *   checksum it carries verifies itself (ADR-0046, ADR-0066) — so the text comes from the
 *   lexicon file and the digest from the ledger, and they are never allowed to meet before
 *   the app compares them;
 * - **text rather than an import**, because `content/` sits outside `apps/mobile/` and Metro
 *   cannot see it without a watch folder;
 * - **committed and `--check`ed**, because a generator whose output is never compared is a
 *   generator nobody is checking [[generating-an-artefact-is-not-checking-it]]. Publishing a
 *   new lexicon and forgetting this step would leave the app on the old vocabulary with every
 *   other gate green.
 *
 * ```
 * node scripts/generate-rules-bundle.mjs           regenerate
 * node scripts/generate-rules-bundle.mjs --check   verify it is current, write nothing
 * ```
 */

import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { loadCorpusPackage, loadRecommendationPackage, ROOT, sha256 } from './corpus-io.mjs';

const GREEN = '\x1b[32m',
  RED = '\x1b[31m',
  DIM = '\x1b[2m',
  BOLD = '\x1b[1m',
  OFF = '\x1b[0m';

const CHECK = process.argv.includes('--check');

const RULES = join(ROOT, 'content', 'rules');
const OUT_DIR = join(ROOT, 'apps', 'mobile', 'src', 'rules', 'generated');
const OUT = join(OUT_DIR, 'lexicon.ts');
const OUT_WEIGHTS = join(OUT_DIR, 'weights.ts');

const { assertSha256, entryDigest, parsePhraseLexicon } = await loadCorpusPackage();
// The ENGINE's own parser, not a reader written here. "These weights load" has to be decided by
// the code that scores with them, or the check agrees with the file on the day it was written
// [[a-check-that-reimplements-its-subject-agrees-with-it-on-day-one]].
const { parseWeightContent, rationaleCount } = await loadRecommendationPackage();

// The generator hashes, so the primitive it hashes with is checked first — same order as the
// publish path. A checksum is a tamper control and cannot rest on an unverified hasher.
assertSha256(sha256);

const ledgerPath = join(RULES, 'index.json');
if (!existsSync(ledgerPath)) {
  console.log(`\n${RED}${BOLD}No rule ledger.${OFF} ${ledgerPath} is missing.\n`);
  process.exit(1);
}

const rows = JSON.parse(readFileSync(ledgerPath, 'utf8'));
const lexiconRows = Array.isArray(rows) ? rows.filter((r) => r.kind === 'phrase-lexicon') : [];
if (lexiconRows.length === 0) {
  console.log(`\n${RED}${BOLD}No phrase-lexicon row in the rule ledger.${OFF}\n`);
  process.exit(1);
}

// The LAST row, like the corpus generator: the newest published version is the one that ships.
// Pinning an older one deliberately would pass every check here, and the committed diff is the
// only record of that decision.
const row = lexiconRows[lexiconRows.length - 1];
const file = `phrase-lexicon.${row.label}.json`;
const text = readFileSync(join(RULES, file), 'utf8');

// Parsed, then digested from the PARSED value — the same path the gate takes, so a file that
// the app could not load cannot be bundled for it to try.
const raw = JSON.parse(text);
const lexicon = parsePhraseLexicon(raw, file);
const actual = entryDigest(raw, sha256);
if (actual !== row.checksum) {
  console.log(
    `\n${RED}${BOLD}The lexicon does not match its ledger row.${OFF}\n` +
      `  file:   ${actual}\n  ledger: ${row.checksum}\n\n` +
      `${DIM}  Published rule content is immutable. A change mints a new version.${OFF}\n`,
  );
  process.exit(1);
}

const generated = `/* eslint-disable */
// prettier-ignore
/**
 * GENERATED by \`node scripts/generate-rules-bundle.mjs\`. Do not edit.
 *
 * The published phrase lexicon as text, and the digest the LEDGER records for it — two exports
 * from two files, because a record checked against a checksum it carries verifies itself
 * (ADR-0046, ADR-0066).
 *
 * Verified current by \`--check\` inside \`gate:content\`, so publishing a new lexicon without
 * regenerating fails the build rather than shipping the old vocabulary.
 */

export const LEXICON_LABEL = ${JSON.stringify(row.label)};

/** Terms in the lexicon. Here so a load can be checked against what was published. */
export const LEXICON_TERM_COUNT = ${String(lexicon.terms.length)};

/** The LEDGER's digest for this lexicon. Never read from the text below. */
export const LEXICON_DIGEST = ${JSON.stringify(row.checksum)};

export const LEXICON_TEXT = ${JSON.stringify(text)};
`;

// --- the weight set (F-099) ------------------------------------------------------------------
//
// Everything below mirrors the lexicon above, step for step, and the steps are the point: the
// LAST published row, the text from the file, the digest from the LEDGER, and a parse through
// the engine before either is written anywhere.

const weightRows = Array.isArray(rows) ? rows.filter((r) => r.kind === 'weights') : [];
if (weightRows.length === 0) {
  console.log(`\n${RED}${BOLD}No weights row in the rule ledger.${OFF}\n`);
  process.exit(1);
}

const weightRow = weightRows[weightRows.length - 1];
const weightFile = `weights.${weightRow.label}.json`;
const weightText = readFileSync(join(RULES, weightFile), 'utf8');
const weightRaw = JSON.parse(weightText);

// Parsed by `parseWeightContent`, which wraps the engine's own `parseRuleSet` — so "these
// weights load" is decided by the code that will score with them. A weight set that does not
// normalise cannot be bundled for the app to fail on later (E-009).
const weights = parseWeightContent(weightRaw, weightFile);
const weightDigest = entryDigest(weightRaw, sha256);
if (weightDigest !== weightRow.checksum) {
  console.log(
    `\n${RED}${BOLD}The weight set does not match its ledger row.${OFF}\n` +
      `  file:   ${weightDigest}\n  ledger: ${weightRow.checksum}\n\n` +
      `${DIM}  Published rule content is immutable. A change mints a new version.${OFF}\n`,
  );
  process.exit(1);
}

const generatedWeights = `/* eslint-disable */
// prettier-ignore
/**
 * GENERATED by \`node scripts/generate-rules-bundle.mjs\`. Do not edit.
 *
 * The published weight set as text, and the digest the LEDGER records for it — two exports from
 * two files, because a record checked against a checksum it carries verifies itself (ADR-0046,
 * ADR-0066).
 *
 * WHY THE APP HAS THIS AT ALL (F-099): the warm/cool POLES live in here, and the app used to
 * carry its own copy of them as literals. Two definitions of one colour rule is E-008's failure
 * exactly — both sides pass their own tests, and they diverge the first time an editor publishes
 * a new pole. The app now reads the same rule set the engine scores with.
 */

export const WEIGHTS_LABEL = ${JSON.stringify(weightRow.label)};

/** Rationales in the set. Here so a load can be checked against what was published. */
export const WEIGHTS_RATIONALE_COUNT = ${String(rationaleCount(weights))};

/** The LEDGER's digest for this weight set. Never read from the text below. */
export const WEIGHTS_DIGEST = ${JSON.stringify(weightRow.checksum)};

export const WEIGHTS_TEXT = ${JSON.stringify(weightText)};
`;

/** Report both artefacts in one line, so a green run says what it checked. */
const summary =
  `${DIM}lexicon ${row.label} (${String(lexicon.terms.length)} term(s)), ` +
  `weights ${weightRow.label} (${String(rationaleCount(weights))} rationale(s))${OFF}`;

if (CHECK) {
  const stale = [
    [OUT, generated, 'lexicon'],
    [OUT_WEIGHTS, generatedWeights, 'weights'],
  ].filter(([path, want]) => (existsSync(path) ? readFileSync(path, 'utf8') : '') !== want);

  if (stale.length > 0) {
    console.log(`\n${RED}${BOLD}${String(stale.length)} generated rule module(s) are stale.${OFF}`);
    for (const [path, , name] of stale) console.log(`${DIM}  ${name}: ${path}${OFF}`);
    console.log(`${DIM}  Run \`node scripts/generate-rules-bundle.mjs\`.${OFF}\n`);
    process.exit(1);
  }
  console.log(`${GREEN}${BOLD}Rule bundle current.${OFF} ${summary}`);
  process.exit(0);
}

mkdirSync(OUT_DIR, { recursive: true });
writeFileSync(OUT, generated, 'utf8');
writeFileSync(OUT_WEIGHTS, generatedWeights, 'utf8');
console.log(`${GREEN}${BOLD}Rule bundle written.${OFF} ${summary}`);
